export function ValueProposition({
  headline = "{{headline}}",
  explanation = "{{explanation}}",
  align = "{{align}}",
  accent = "{{accent}}",
  showIcon = {{showIcon}},
}) {
  const centered = align === "center";
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 340,
      textAlign: align, margin: centered ? "0 auto" : 0 }}>
      {showIcon && (
        <span aria-hidden="true" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center",
          width: 32, height: 32, borderRadius: "50%", color: "#241430", fontWeight: 700, marginBottom: 12, background: accent }}>&#10003;</span>
      )}
      <h3 style={{ margin: "0 0 8px", fontSize: 20, fontWeight: 700 }}>{headline}</h3>
      <p style={{ margin: 0, color: "#241430cc", fontSize: 14 }}>{explanation}</p>
    </div>
  );
}
